package run.ikaros.reading; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.IfMatchVersion;
@RestController @RequestMapping("/api/v2/reading") public class ReadingProgressController{private final ReadingProgressService service;public ReadingProgressController(ReadingProgressService s){service=s;}@PostMapping("/works/{workId}/sessions")public Mono<ReadingSessionView> start(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID workId,@Valid@RequestBody StartReadingSessionRequest r){return service.start(o,workId,r);}@PatchMapping("/sessions/{sessionId}")public Mono<ResponseEntity<ReadingSessionView>> update(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID sessionId,@RequestHeader(value="If-Match",required=false)String ifMatch,@Valid@RequestBody UpdateReadingProgressRequest r){return service.update(o,sessionId,r,IfMatchVersion.parse(ifMatch)).map(view->ResponseEntity.ok().eTag(IfMatchVersion.etag(view.version())).body(view));}@PostMapping("/sessions/{sessionId}/actions/end")public Mono<ResponseEntity<ReadingSessionView>> end(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID sessionId,@RequestHeader(value="If-Match",required=false)String ifMatch){return service.end(o,sessionId,IfMatchVersion.parse(ifMatch)).map(view->ResponseEntity.ok().eTag(IfMatchVersion.etag(view.version())).body(view));}@GetMapping("/works/{workId}/progress")public Mono<ReadingProgressView> progress(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID workId,@RequestParam UUID editionId){return service.progress(o,workId,editionId);}@GetMapping("/history")public Flux<ReadingHistoryView> history(@RequestHeader("X-Ikaros-Actor-Id")UUID o){return service.history(o);}}
